"use client";
import { createContext, lazy, Suspense, useContext, useId, useState, type ReactNode, } from "react";
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";
import { cn } from "@lib/utils";
import { usePortalContainer } from "@lib/portal-container-context";
const TooltipMotionPopup = lazy(() => import("./tooltip-motion-popup"));
// ---------------------------------------------------------------------------
// Portal container context
// ---------------------------------------------------------------------------
const TooltipPortalContainerContext = createContext<HTMLElement | null>(null);
function TooltipPortalContainer({ value, children, }: {
    value: HTMLElement | null;
    children: ReactNode;
}) {
    return (<TooltipPortalContainerContext.Provider value={value}>
      {children}
    </TooltipPortalContainerContext.Provider>);
}
// ---------------------------------------------------------------------------
// Provider
// ---------------------------------------------------------------------------
const DEFAULT_DELAY = 200;
// Tracks whether an app-level <TooltipProvider> is above us. Each Tooltip
// only wraps itself in a local primitive Provider when there isn't one —
// a per-instance Provider would defeat cross-tooltip skip-delay grouping
// (moving between adjacent tooltips would re-wait the full delay).
const TooltipGroupContext = createContext(false);
interface TooltipProviderProps {
    children: ReactNode;
    /** Hover delay before tooltips open, in ms. Defaults to 200. */
    delayDuration?: number;
    /** After a tooltip closes, adjacent tooltips opened within this window
     *  skip the hover delay, in ms. Defaults to 300. */
    skipDelayDuration?: number;
}
/** Groups descendant Tooltips so that once one opens, moving to an adjacent
 *  trigger shows its tooltip instantly instead of re-waiting the full delay.
 *  Wrap once at the app (or section) level; bare Tooltips still work without
 *  it via a per-instance fallback. */
function TooltipProvider({ children, delayDuration = DEFAULT_DELAY, skipDelayDuration = 300, }: TooltipProviderProps) {
    return (<TooltipGroupContext.Provider value={true}>
      <TooltipPrimitive.Provider delay={delayDuration} timeout={skipDelayDuration}>
        {children}
      </TooltipPrimitive.Provider>
    </TooltipGroupContext.Provider>);
}
// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------
type TooltipSide = "top" | "right" | "bottom" | "left";
interface TooltipProps {
    content: ReactNode;
    children: React.ReactElement;
    side?: TooltipSide;
    sideOffset?: number;
    /** Hover delay before this tooltip opens, in ms. Defaults to 200, or to the
     *  ambient TooltipProvider's delayDuration when one is present. */
    delayDuration?: number;
    className?: string;
    /** When true, forces the tooltip open. When false, forces it closed. When undefined, uses default hover/focus behavior. */
    forceOpen?: boolean;
    /** Called when the tooltip's internal open state changes (before forceOpen is applied). */
    onOpenChange?: (open: boolean) => void;
}
// ---------------------------------------------------------------------------
// Animation helpers
// ---------------------------------------------------------------------------
function getSlideOffset(side: TooltipSide) {
    switch (side) {
        case "top":
            return { y: 4 };
        case "bottom":
            return { y: -4 };
        case "left":
            return { x: 4 };
        case "right":
            return { x: -4 };
    }
}
// ---------------------------------------------------------------------------
// Tooltip
// ---------------------------------------------------------------------------
function Tooltip({ content, children, side = "top", sideOffset = 8, delayDuration, className, forceOpen, onOpenChange: onOpenChangeProp, }: TooltipProps) {
    const generatedId = useId();
    const childProps = children.props as {
        id?: string;
        "aria-describedby"?: string;
    };
    const triggerId = childProps.id ?? generatedId;
    const contentId = `${triggerId}-tooltip`;
    const [internalOpen, setInternalOpen] = useState(false);
    const open = forceOpen !== undefined ? forceOpen : internalOpen;
    const portalContainer = useContext(TooltipPortalContainerContext);
    const fullscreenPortal = usePortalContainer();
    const hasAmbientProvider = useContext(TooltipGroupContext);
    const slideOffset = getSlideOffset(side);
    const tooltip = (<TooltipPrimitive.Root open={open} triggerId={forceOpen !== undefined ? triggerId : undefined} onOpenChange={(v) => {
            setInternalOpen(v);
            onOpenChangeProp?.(v);
        }}>
      {/* An explicit delayDuration overrides the ambient provider's delay;
            left undefined, the trigger inherits it from the provider. */}
      <TooltipPrimitive.Trigger id={triggerId} aria-describedby={[childProps["aria-describedby"], open ? contentId : undefined].filter(Boolean).join(" ") || undefined} render={children} delay={delayDuration}/>
      <TooltipPrimitive.Portal container={portalContainer ?? fullscreenPortal ?? undefined}>
        <TooltipPrimitive.Positioner side={side} sideOffset={sideOffset} className="z-popover">
          <TooltipPrimitive.Popup role="tooltip" id={contentId} render={(props, state) => {
            const popupProps = {
                ...props,
                className: cn("bg-inverse-background text-fg-on-inverse text-label px-2 py-1", "rounded-lg font-medium", className),
            };
            return (<Suspense fallback={<div {...popupProps}/>}>
                  <TooltipMotionPopup {...popupProps} slideOffset={slideOffset} starting={state.transitionStatus === "starting"} exiting={state.transitionStatus === "ending"}/>
                </Suspense>);
        }}>
            {content}
          </TooltipPrimitive.Popup>
        </TooltipPrimitive.Positioner>
      </TooltipPrimitive.Portal>
    </TooltipPrimitive.Root>);
    // Fallback: without an ambient TooltipProvider, give this instance its own
    // so a bare <Tooltip> keeps the library's default delay. Grouped skip-delay
    // needs the shared app-level TooltipProvider.
    if (hasAmbientProvider)
        return tooltip;
    return (<TooltipPrimitive.Provider delay={delayDuration ?? DEFAULT_DELAY}>
      {tooltip}
    </TooltipPrimitive.Provider>);
}
export { Tooltip, TooltipPortalContainer, TooltipProvider };
export type { TooltipProps, TooltipProviderProps, TooltipSide };

"use client";
import type { ComponentPropsWithRef } from "react";
import { motion } from "motion/react";
import { spring } from "@lib/springs";
export default function TooltipMotionPopup({ slideOffset, starting, exiting, 
// Let Motion own the drag and animation callbacks on the popup.
onDrag: _onDrag, onDragStart: _onDragStart, onDragEnd: _onDragEnd, onAnimationStart: _onAnimationStart, onAnimationEnd: _onAnimationEnd, onAnimationIteration: _onAnimationIteration, ...props }: ComponentPropsWithRef<"div"> & {
    slideOffset: {
        x?: number;
        y?: number;
    };
    starting: boolean;
    exiting: boolean;
}) {
    const closed = { opacity: 0, ...slideOffset };
    return <motion.div {...props} initial={starting ? closed : false} animate={exiting ? closed : { opacity: 1, x: 0, y: 0 }} transition={exiting ? spring.fast.exit : spring.fast}/>;
}
